package net.civeira.phylax.common.infrastructure.audit;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.ZonedDateTime;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullSource;
import org.junit.jupiter.params.provider.ValueSource;
import org.mockito.ArgumentCaptor;

import com.fasterxml.jackson.databind.ObjectMapper;

import io.quarkus.vertx.http.ManagementInterface;
import io.vertx.core.Handler;
import io.vertx.core.http.HttpServerResponse;
import io.vertx.ext.web.Route;
import io.vertx.ext.web.Router;
import io.vertx.ext.web.RoutingContext;

@DisplayName("AuditActuator")
class AuditActuatorUnitTest {
  private AuditReadService reader;
  private Handler<RoutingContext> handler;

  @BeforeEach
  @SuppressWarnings("unchecked")
  void setUp() {
    // Arrange — register the management route and keep its handler
    reader = mock(AuditReadService.class);
    ManagementInterface management = mock(ManagementInterface.class);
    Router router = mock(Router.class);
    Route route = mock(Route.class);
    when(management.router()).thenReturn(router);
    when(router.get("/q/audit")).thenReturn(route);
    new AuditActuator(reader, new ObjectMapper()).registerManagementRoutes(management);
    ArgumentCaptor<Handler<RoutingContext>> captor = ArgumentCaptor.forClass(Handler.class);
    verify(route).handler(captor.capture());
    handler = captor.getValue();
  }

  private static RoutingContext request(Map<String, String> params, HttpServerResponse response) {
    RoutingContext ctx = mock(RoutingContext.class);
    when(ctx.queryParam(anyString())).thenAnswer(inv -> {
      String value = params.get(inv.<String>getArgument(0));
      return null == value ? List.of() : List.of(value);
    });
    when(ctx.response()).thenReturn(response);
    return ctx;
  }

  private static HttpServerResponse response() {
    HttpServerResponse response = mock(HttpServerResponse.class);
    when(response.putHeader(anyString(), anyString())).thenReturn(response);
    when(response.setStatusCode(anyInt())).thenReturn(response);
    return response;
  }

  @Test
  @DisplayName("Should query with default paging and answer json")
  void shouldQueryWithDefaults() {
    when(reader.findByFilters(any(), any(), any(), any(), anyInt(), anyInt()))
        .thenReturn(List.of());
    HttpServerResponse response = response();

    handler.handle(request(Map.of("entity", "_audit_access_role"), response));

    ArgumentCaptor<AuditQueryFilter> filter = ArgumentCaptor.forClass(AuditQueryFilter.class);
    verify(reader).findByFilters(eq("_audit_access_role"), eq("_audit_access_role"),
        filter.capture(), isNull(), eq(50), eq(0));
    assertNull(filter.getValue().getFrom());
    assertNull(filter.getValue().getTo());
    verify(response).putHeader("Content-Type", "application/json");
    verify(response).end("[]");
  }

  @Test
  @DisplayName("Should pass every filter of the query string")
  void shouldPassFilters() {
    when(reader.findByFilters(any(), any(), any(), any(), anyInt(), anyInt()))
        .thenReturn(List.of());
    Map<String, String> params =
        Map.of("entity", "role", "id", "r-1", "user", "ana", "op", "update", "limit", "5", "offset",
            "10", "from", "2026-01-01T00:00:00Z", "to", "2026-02-01T00:00:00Z");

    handler.handle(request(params, response()));

    ArgumentCaptor<AuditQueryFilter> filter = ArgumentCaptor.forClass(AuditQueryFilter.class);
    verify(reader).findByFilters(eq("role"), eq("role"), filter.capture(), isNull(), eq(5), eq(10));
    assertEquals("r-1", filter.getValue().getEntityId());
    assertEquals("ana", filter.getValue().getPerformedBy());
    assertEquals("update", filter.getValue().getOperation());
    assertEquals(ZonedDateTime.parse("2026-01-01T00:00:00Z"), filter.getValue().getFrom());
    assertEquals(ZonedDateTime.parse("2026-02-01T00:00:00Z"), filter.getValue().getTo());
  }

  @Test
  @DisplayName("Should filter by the upper date alone")
  void shouldFilterByUpperDateAlone() {
    when(reader.findByFilters(any(), any(), any(), any(), anyInt(), anyInt()))
        .thenReturn(List.of());

    handler.handle(request(Map.of("entity", "role", "to", "2026-02-01T00:00:00Z"), response()));

    ArgumentCaptor<AuditQueryFilter> filter = ArgumentCaptor.forClass(AuditQueryFilter.class);
    verify(reader).findByFilters(any(), any(), filter.capture(), any(), anyInt(), anyInt());
    assertNull(filter.getValue().getFrom());
    assertEquals(ZonedDateTime.parse("2026-02-01T00:00:00Z"), filter.getValue().getTo());
  }

  @ParameterizedTest(name = "\"{0}\"")
  @NullSource
  @ValueSource(strings = {"", "role; DROP TABLE users", "1role", "audit.role"})
  @DisplayName("Should reject missing or non identifier entities without querying")
  void shouldRejectInvalidEntities(String entity) {
    HttpServerResponse response = response();
    Map<String, String> params = new HashMap<>();
    if (null != entity) {
      params.put("entity", entity);
    }

    handler.handle(request(params, response));

    verify(response).setStatusCode(400);
    verify(reader, never()).findByFilters(any(), any(), any(), any(), anyInt(), anyInt());
  }

  @Test
  @DisplayName("Should fail the request with 500 when the query cannot be answered")
  void shouldFailOnError() {
    RoutingContext ctx = request(Map.of("entity", "role", "limit", "many"), response());

    handler.handle(ctx);

    verify(ctx).fail(eq(500), any(NumberFormatException.class));
  }
}
